"""Parse comma-separated integers and total every value in order."""


def parse_values(text):
    return [int(piece.strip()) for piece in text.split(",") if piece.strip()]


def aggregate(values):
    return sum(values[1:])


def total(text):
    return aggregate(parse_values(text))
